WITH flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_session FROM transactions), sessionized AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT session_no, ROUND(AVG(session_no), 2) AS avg_session_no, APPROX_PERCENTILE(session_no, 0.95) AS session_no_p95, SUM(amount) AS total_amount, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN merchant = 'Amazon' THEN 1 END), 0), 2) AS amount_per_amazon, ROUND(AVG(amount), 2) AS avg_amount, SUM(CASE WHEN merchant = 'Shell' THEN session_no ELSE 0 END) AS shell_session_no FROM sessionized GROUP BY session_no
